# Define cosmological events and their parameters
cosmic_events = {
    "Recombination Era": {"time_years": 380000, "temperature_K": 3000},
    "Matter-Radiation Equality": {"time_years": 50000, "temperature_K": 16000},
    "Today": {"time_years": 13.8e9, "temperature_K": 2.7},  # Age of universe in years
}

# Magnification factor
magnification = 35

# Apply magnification to time and temperature
def apply_magnification(events, magnification):
    results = {}
    for event, params in events.items():
        magnified_time = params["time_years"] * magnification  # Magnified time in years
        magnified_temperature = params["temperature_K"] * magnification  # Magnified temperature
        results[event] = {
            "magnified_time_years": magnified_time,
            "magnified_temperature_K": magnified_temperature,
        }
    return results

# Perform analysis
magnified_cosmic_results = apply_magnification(cosmic_events, magnification)

# Return magnified results
magnified_cosmic_results

